/* Alloq component styles: static renditions of the Reflex/Mantine components, built on tokens.css. */
.aq{font-family:var(--font-sans);color:var(--text);font-size:14px;line-height:1.45;-webkit-font-smoothing:antialiased}
.aq *,.aq *::before,.aq *::after{box-sizing:border-box}
.aq-ground{background:var(--bg-base);min-height:100%}
.aq-pad{padding:20px}
.aq-row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}
.aq-stack{display:flex;flex-direction:column;gap:16px}
.aq-muted{color:var(--text-muted)}
.aq-icon{width:16px;height:16px;stroke-width:1.5;flex-shrink:0}
.aq-icon-lg{width:20px;height:20px}

/* Buttons */
.aq-btn{font:inherit;font-size:14px;font-weight:600;height:36px;padding:0 18px;border-radius:var(--radius-md);border:1px solid transparent;display:inline-flex;align-items:center;gap:8px;cursor:pointer;transition:background-color 120ms ease}
.aq-btn-sm{height:30px;padding:0 14px;font-size:13px}
.aq-btn-filled{background:var(--primary-filled);color:var(--nav-active-text)}
.aq-btn-filled:hover{background:var(--primary-filled-hover)}
.aq-btn-light{background:var(--accent-soft);color:var(--teal-7)}
.aq-btn-light:hover{background:var(--surface-hover)}
.aq-btn-outline{background:transparent;color:var(--text);border-color:var(--border-strong)}
.aq-btn-outline:hover{background:var(--surface-hover)}
.aq-btn-subtle{background:transparent;color:var(--teal-7)}
.aq-btn-subtle:hover{background:var(--nav-hover-bg)}
.aq-btn-danger{background:var(--red-6);color:#fff}
.aq-btn:disabled{opacity:.5;cursor:not-allowed}
.aq-btn:focus-visible,.aq-ai:focus-visible,.aq-input:focus-within{outline:2px solid var(--accent);outline-offset:2px}
[data-theme="dark"] .aq-btn-light,[data-theme="dark"] .aq-btn-subtle{color:var(--teal-3)}

/* Action icons */
.aq-ai{width:36px;height:36px;border-radius:var(--radius-md);display:inline-flex;align-items:center;justify-content:center;border:0;cursor:pointer;background:transparent;color:var(--text)}
.aq-ai-sm{width:22px;height:22px;border-radius:var(--radius-sm)}
.aq-ai-filled{background:var(--primary-filled);color:var(--nav-active-text)}
.aq-ai-filled:hover{background:var(--primary-filled-hover)}
.aq-ai-subtle:hover{background:var(--nav-hover-bg)}
.aq-ai-danger{color:var(--red-6)}
.aq-ai-danger:hover{background:rgba(226,98,84,.12)}
.aq-ai-gray{color:var(--text-muted)}

/* Inputs */
.aq-field{display:grid;gap:4px;font-size:14px;font-weight:500}
.aq-input{height:36px;border:1px solid var(--border-strong);border-radius:var(--radius-md);background:var(--surface-solid);display:flex;align-items:center;gap:8px;padding:0 12px;font-weight:400;color:var(--text)}
.aq-input-sm{height:30px;font-size:13px}
.aq-input .ph{color:var(--text-muted)}
.aq-input .chev{margin-left:auto;color:var(--text-muted)}
.aq-hint{font-size:12px;color:var(--text-muted);font-weight:400}
.aq-error{font-size:12px;color:var(--red-6);font-weight:400}
.aq-input.is-error{border-color:var(--red-4)}
.aq-switch{display:inline-flex;align-items:center;gap:8px;font-size:13px}
.aq-switch i{width:32px;height:18px;border-radius:9px;background:var(--meter-track);border:1px solid var(--border-strong);position:relative}
.aq-switch i::after{content:"";position:absolute;top:2px;left:2px;width:12px;height:12px;border-radius:50%;background:var(--surface-solid);box-shadow:0 1px 2px rgba(0,0,0,.2)}
.aq-switch.on i{background:var(--primary-filled);border-color:var(--primary-filled)}
.aq-switch.on i::after{left:16px}
.aq-pillbox{display:flex;gap:4px;align-items:center;flex-wrap:wrap}
.aq-pill{display:inline-flex;align-items:center;gap:4px;padding:1px 8px;border-radius:var(--radius-sm);background:var(--tag-bg);font-size:12px}

/* Segmented control */
.aq-seg{display:inline-flex;padding:4px;gap:2px;border-radius:var(--radius-md);background:var(--meter-track)}
.aq-seg span{display:inline-flex;align-items:center;gap:6px;padding:4px 12px;border-radius:6px;font-size:13px;font-weight:500;color:var(--text-muted);cursor:pointer}
.aq-seg span.on{background:var(--gray-9);color:#fff;box-shadow:var(--shadow-card)}
[data-theme="dark"] .aq-seg span.on{background:var(--surface-hover);color:var(--text)}

/* Tabs */
.aq-tabs{display:flex;gap:4px;border-bottom:1px solid var(--border)}
.aq-tabs span{padding:8px 14px;font-size:14px;font-weight:500;color:var(--text-muted);border-bottom:2px solid transparent;margin-bottom:-1px;cursor:pointer}
.aq-tabs span.on{color:var(--text);border-bottom-color:var(--accent)}

/* Badges and avatars */
.aq-badge{display:inline-flex;align-items:center;gap:6px;height:22px;padding:0 10px;border-radius:999px;font-size:12px;font-weight:700;white-space:nowrap}
.aq-badge-sm{height:18px;padding:0 8px;font-size:11px}
.aq-badge-square{border-radius:var(--radius-sm)}
.aq-badge .dot{width:6px;height:6px;border-radius:50%;background:currentColor}
.aq-b-gray{background:var(--gray-light);color:var(--gray-7)}
.aq-b-green{background:var(--green-light);color:var(--green-7)}
.aq-b-red{background:var(--red-light);color:var(--red-7)}
.aq-b-blue{background:var(--blue-light);color:var(--blue-7)}
.aq-b-orange{background:var(--orange-light);color:var(--orange-7)}
.aq-b-yellow{background:var(--yellow-light);color:var(--yellow-7)}
.aq-b-tag{background:var(--tag-bg);color:var(--text);font-weight:400}
.aq-b-filled-red{background:var(--red-4);color:#fff}
.aq-b-filled-orange{background:var(--orange-4);color:#fff}
.aq-b-outline{background:transparent;border:1px solid var(--border-strong);color:var(--text-muted);font-weight:600}
[data-theme="dark"] .aq-b-gray{color:var(--gray-4)}
[data-theme="dark"] .aq-b-green{color:var(--green-3)}
[data-theme="dark"] .aq-b-red{color:var(--red-3)}
[data-theme="dark"] .aq-b-blue{color:var(--blue-3)}
[data-theme="dark"] .aq-b-orange{color:var(--orange-3)}
[data-theme="dark"] .aq-b-yellow{color:var(--yellow-3)}
.aq-av{width:38px;height:38px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:14px;font-weight:700;background:var(--accent-soft);color:var(--accent-strong);flex-shrink:0}
.aq-av-sm{width:26px;height:26px;font-size:11px}
.aq-av-lg{width:56px;height:56px;font-size:18px;border-radius:var(--radius-md);color:#fff;font-weight:800}
.aq-avg{display:flex}
.aq-avg .aq-av{border:2px solid var(--surface-solid);margin-left:-8px}
.aq-avg .aq-av:first-child{margin-left:0}

/* Progress */
.aq-progress{height:8px;border-radius:999px;background:var(--meter-track);overflow:hidden}
.aq-progress>i{display:block;height:100%;border-radius:inherit;background:var(--teal-6)}

/* Cards */
.aq-card{background:var(--fade-bg);border-radius:var(--radius-lg);padding:20px;transition:background-color 120ms ease;cursor:pointer}
.aq-card:hover{background:var(--fade-bg-hover)}
.aq-card-border{border:1px solid var(--border)}
.aq-section{background:var(--fade-bg);border-radius:8px;padding:18px;box-shadow:0 8px 24px rgba(0,0,0,.04);display:flex;flex-direction:column;gap:16px}
.aq-card-title{font-size:18px;font-weight:700}
.aq-label-caps{font-size:14px;font-weight:600;letter-spacing:.02em;text-transform:uppercase;color:var(--text-muted)}
.aq-metric-label{font-size:10.4px;font-weight:800;color:var(--text-muted);letter-spacing:.02em}
.aq-metric-value{font-size:14px;font-weight:800}
.aq-stat{font-size:36px;font-weight:700;line-height:1}
.aq-stat small{font-size:20px;font-weight:400;color:var(--text-muted)}

/* Navigation */
.aq-rail{width:64px;padding:12px 8px;display:flex;flex-direction:column;gap:6px;align-items:center;background:var(--nav-bg);border-right:1px solid var(--border)}
.aq-panel{width:240px;padding:12px;display:flex;flex-direction:column;gap:4px;background:var(--nav-panel-bg);border-right:1px solid var(--border)}
.aq-nav-i{width:44px;height:44px;border-radius:8px;display:flex;align-items:center;justify-content:center;color:var(--text);transition:background-color .2s ease;cursor:pointer}
.aq-nav-i:hover{background:var(--nav-hover-bg)}
.aq-nav-i.on{background:var(--nav-active-bg);color:var(--nav-active-text)}
.aq-nav-link{display:flex;align-items:center;gap:12px;padding:8px 12px;border-radius:8px;font-size:14px;color:var(--text);cursor:pointer}
.aq-nav-link:hover{background:var(--nav-hover-bg)}
.aq-nav-link.on{background:var(--nav-active-bg);color:var(--nav-active-text)}
.aq-panel-title{font-size:12px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--text-muted);padding:6px 12px}

/* Tooltip and menu */
.aq-tip{display:inline-block;position:relative;background:var(--gray-9);color:#fff;font-size:12px;padding:5px 10px;border-radius:var(--radius-sm)}
.aq-tip::after{content:"";position:absolute;top:-4px;left:50%;margin-left:-4px;border:4px solid transparent;border-top:0;border-bottom-color:var(--gray-9)}
.aq-menu{background:var(--surface-solid);border:1px solid var(--border);border-radius:var(--radius-md);box-shadow:var(--shadow-soft);padding:4px;min-width:180px}
.aq-menu div{display:flex;gap:8px;align-items:center;padding:7px 10px;border-radius:var(--radius-sm);font-size:14px}
.aq-menu div:hover{background:var(--surface-hover)}
.aq-menu .danger{color:var(--red-6)}

/* Modal and drawer */
.aq-modal{background:var(--surface-muted);border:1px solid var(--border);border-radius:var(--radius-lg);overflow:hidden;box-shadow:var(--shadow-soft)}
.aq-modal-h{padding:16px 18px 8px 36px;font-size:19px;font-weight:700;display:flex;justify-content:space-between;align-items:center}
.aq-modal-b{padding:16px 18px;display:flex;flex-direction:column;gap:12px}
.aq-modal-f{background:var(--surface-solid);padding:16px 18px 18px;display:flex;justify-content:flex-end;gap:16px;box-shadow:var(--shadow-footer)}
.aq-overlay{background:rgba(0,0,0,.3);backdrop-filter:blur(3px)}

/* Table */
.aq-table-w{background:var(--fade-bg);border-radius:var(--radius-sm);overflow:auto}
.aq-table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:14px}
.aq-table th{position:sticky;top:0;background:var(--surface-solid);text-align:left;font-weight:600;padding:10px 14px;border-bottom:1px solid var(--border)}
.aq-table td{padding:10px 14px;border-bottom:1px solid var(--border);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aq-table tr:hover td{background:var(--surface-hover)}
.aq-num{font-variant-numeric:tabular-nums;text-align:right}

/* Planning grid */
.aq-grid{display:grid;background:var(--surface-solid);border:1px solid var(--border);border-radius:var(--radius-sm);overflow:auto;font-size:13px;font-variant-numeric:tabular-nums}
.aq-grid>div{display:flex;align-items:center;justify-content:center;min-height:32px;padding:0 4px;border-right:1px solid var(--border);border-bottom:1px solid var(--border)}
.aq-grid .lbl{justify-content:flex-start;padding:0 12px;gap:8px;background:var(--surface-solid);position:sticky;left:0;z-index:2}
.aq-grid .month{background:var(--accent-soft);font-size:11px;font-weight:700;justify-content:flex-start;padding-left:12px;min-height:30px}
.aq-grid .week{background:var(--surface-muted);font-size:11px;font-weight:500;color:var(--text-muted);min-height:30px}
.aq-grid .now{background:var(--current-week)}
.aq-grid .emp{background:var(--surface-hover);font-weight:700;border-top:1px solid var(--border-strong);border-bottom:1px solid var(--border-strong)}
.aq-grid .sum{background:var(--surface-muted)}
.aq-swatch{width:10px;height:10px;border-radius:3px;flex-shrink:0}
.cap-available{background:var(--cap-available-bg);color:var(--cap-available-fg)}
.cap-balanced{background:var(--cap-balanced-bg);color:var(--cap-balanced-fg)}
.cap-tight{background:var(--cap-tight-bg);color:var(--cap-tight-fg)}
.cap-over{background:var(--cap-over-bg);color:var(--cap-over-fg)}
.cap-absent{background:var(--cap-absent-bg);color:var(--cap-absent-fg)}

/* Heatmap */
.aq-heat{display:inline-flex;align-items:center;justify-content:center;gap:4px;min-width:48px;height:24px;padding:0 8px;border-radius:999px;font-size:12px;font-weight:600;font-variant-numeric:tabular-nums}
.heat-low{background:var(--heat-low-bg);color:var(--heat-low-fg)}
.heat-mid{background:var(--heat-mid-bg);color:var(--heat-mid-fg)}
.heat-high{background:var(--heat-high-bg);color:var(--heat-high-fg)}
.heat-over{background:var(--heat-over-bg);color:var(--heat-over-fg)}
.heat-absent{color:var(--heat-absent-fg);background:repeating-linear-gradient(45deg,rgba(0,0,0,.04),rgba(0,0,0,.04) 4px,rgba(0,0,0,.1) 4px,rgba(0,0,0,.1) 8px)}
[data-theme="dark"] .heat-absent{background:repeating-linear-gradient(45deg,rgba(255,255,255,.05),rgba(255,255,255,.05) 4px,rgba(255,255,255,.12) 4px,rgba(255,255,255,.12) 8px)}

/* Gantt */
.aq-gantt{position:relative;background:var(--surface-solid);border:1px solid var(--border);border-radius:var(--radius-sm)}
.aq-gantt-bar{position:absolute;height:24px;border-radius:4px;background:var(--accent-strong);color:#fff;font-size:12px;font-weight:600;text-align:center;line-height:24px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;padding:0 6px}

/* Lists, empty state */
.aq-list-row{display:flex;align-items:center;gap:12px;padding:10px 12px;border-radius:var(--radius-md);cursor:pointer}
.aq-list-row:hover{background:var(--surface-hover)}
.aq-item{background:var(--item-bg);color:var(--item-text);border-radius:6px;padding:6px 10px;font-size:10.6px;display:flex;align-items:center;justify-content:space-between;min-height:32px}
.aq-empty{display:flex;flex-direction:column;align-items:center;gap:8px;padding:40px 20px;text-align:center}
.aq-empty .aq-icon{width:48px;height:48px;color:var(--gray-5);stroke-width:1.25}
.aq-skel{border-radius:var(--radius-sm);background:linear-gradient(90deg,var(--meter-track),var(--surface-hover),var(--meter-track));background-size:200% 100%;animation:aq-sk 1.4s ease infinite}
@keyframes aq-sk{from{background-position:200% 0}to{background-position:-200% 0}}
@media (prefers-reduced-motion:reduce){.aq-skel{animation:none}}

